:root {
  --ink: #141311;
  --paper: #f4f0e6;
  --orange: #ff5a1f;
  --orange-soft: #ff8a4c;
  --acid: #d7ff3f;
  --cyan: #6ef3d6;
  --muted: #a6a096;
  --line: rgba(244, 240, 230, 0.16);
  --panel: rgba(15, 14, 12, 0.82);
  --display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
  --mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  --body: "Helvetica Neue", Arial, system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #0e0d0b;
  color: var(--paper);
  font-family: var(--body);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
  user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 46%, rgba(5, 4, 3, 0.32) 100%),
    linear-gradient(to bottom, rgba(5, 4, 3, 0.2), transparent 18%, transparent 82%, rgba(5, 4, 3, 0.26));
  z-index: 2;
}

#flash {
  position: absolute;
  inset: 0;
  background: #fff;
  opacity: 0;
  pointer-events: none;
  z-index: 20;
  mix-blend-mode: screen;
  transition: opacity 120ms linear;
}
#flash.on { opacity: 0.22; }

.hidden { display: none !important; }

/* ============================================================ HUD */

#hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: max(14px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) 14px max(18px, env(safe-area-inset-left));
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  filter: drop-shadow(0 2px 8px rgba(0,0,0,0.5));
}
.brand-slash {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border: 2px solid var(--paper);
  font: 900 17px/1 var(--display);
  letter-spacing: -1px;
  transform: skew(-8deg);
  background: rgba(10, 9, 8, 0.4);
}
.brand-slash span { color: var(--orange); }
.brand-copy { display: flex; flex-direction: column; gap: 3px; }
.brand-copy strong { font: 900 15px/1 var(--display); letter-spacing: -0.4px; }
.brand-copy strong span { color: var(--orange); }
.brand-copy em { font: 500 9px/1 var(--mono); letter-spacing: 2px; color: var(--muted); font-style: normal; }

.timer-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 6px 18px 8px;
  background: linear-gradient(to bottom, rgba(12, 11, 9, 0.72), rgba(12, 11, 9, 0.15));
  border-radius: 0 0 14px 14px;
  border: 1px solid var(--line);
  border-top: 0;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
#timer {
  font: 800 clamp(26px, 3.2vw, 40px)/1 var(--mono);
  letter-spacing: -2px;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 14px rgba(0,0,0,0.45);
}
#timer.low { color: var(--orange); animation: pulse 0.9s infinite; }
@keyframes pulse { 50% { opacity: 0.55; } }
.hud-label { font: 600 8px/1 var(--mono); letter-spacing: 3px; color: var(--muted); }

.letter-row { display: flex; gap: 4px; margin-top: 4px; }
.letter-row b {
  display: grid;
  place-items: center;
  width: 16px;
  height: 16px;
  font: 800 9px/1 var(--mono);
  color: rgba(244, 240, 230, 0.3);
  border: 1px solid rgba(244, 240, 230, 0.14);
  border-radius: 3px;
  transition: all 180ms ease;
}
.letter-row b.got {
  color: var(--ink);
  background: var(--acid);
  border-color: var(--acid);
  box-shadow: 0 0 14px rgba(215, 255, 63, 0.55);
  transform: translateY(-1px) rotate(-4deg);
}

.score-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 3px;
  filter: drop-shadow(0 2px 8px rgba(0,0,0,0.45));
}
#score {
  font: 900 clamp(28px, 3.4vw, 44px)/0.9 var(--display);
  letter-spacing: -2px;
  font-variant-numeric: tabular-nums;
}
.hud-buttons { display: flex; gap: 6px; margin-top: 6px; pointer-events: auto; }
.icon-btn {
  width: 30px;
  height: 30px;
  border: 1px solid var(--line);
  background: rgba(14, 13, 11, 0.6);
  color: var(--paper);
  border-radius: 50%;
  font: 700 13px/1 var(--mono);
  cursor: pointer;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition: background 140ms ease, border-color 140ms ease;
}
.icon-btn:hover { background: rgba(255, 90, 31, 0.2); border-color: var(--orange); }
.icon-btn.muted { color: var(--muted); text-decoration: line-through; }

#combo-wrap {
  position: absolute;
  top: 112px;
  right: max(18px, env(safe-area-inset-right));
  display: flex;
  align-items: stretch;
  gap: 8px;
  animation: slideIn 180ms ease both;
}
@keyframes slideIn { from { transform: translateX(20px); opacity: 0; } }
#combo-mult {
  display: grid;
  place-items: center;
  padding: 6px 10px;
  background: var(--orange);
  color: var(--ink);
  font: 900 22px/1 var(--display);
  letter-spacing: -1px;
  transform: skew(-7deg);
  box-shadow: 0 6px 24px rgba(255, 90, 31, 0.35);
}
.combo-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  min-width: 92px;
  padding: 6px 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-left: 3px solid var(--orange);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
#combo-bank { font: 800 16px/1 var(--mono); font-variant-numeric: tabular-nums; }
#combo-bar { display: block; width: 100%; height: 3px; background: rgba(255,255,255,0.12); overflow: hidden; }
#combo-bar b { display: block; height: 100%; width: 100%; background: var(--acid); transform-origin: left; transition: transform 80ms linear; }

#trick-feed {
  position: absolute;
  top: 108px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: min(70vw, 560px);
  pointer-events: none;
}
.trick-line {
  font: 800 clamp(13px, 1.5vw, 19px)/1.35 var(--display);
  letter-spacing: 1px;
  color: var(--paper);
  text-shadow: 0 2px 10px rgba(0,0,0,0.7);
  animation: trickIn 160ms cubic-bezier(.2,.9,.3,1.2) both;
  white-space: nowrap;
}
.trick-line i { color: var(--acid); font-style: normal; font-family: var(--mono); font-size: 0.75em; margin-left: 8px; }
.trick-line.fade { animation: trickOut 500ms ease forwards; }
@keyframes trickIn { from { transform: translateY(10px) scale(0.88); opacity: 0; } }
@keyframes trickOut { to { opacity: 0; transform: translateY(-10px); } }

#center-toast {
  position: absolute;
  top: 32%;
  left: 50%;
  transform: translate(-50%, -50%) skew(-6deg);
  padding: 8px 22px;
  background: rgba(12, 11, 9, 0.7);
  border: 1px solid var(--line);
  border-left: 4px solid var(--acid);
  font: 900 clamp(22px, 4vw, 44px)/1 var(--display);
  letter-spacing: -1px;
  white-space: nowrap;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  animation: toastIn 220ms cubic-bezier(.2,.9,.3,1.2) both;
  text-shadow: 0 4px 20px rgba(0,0,0,0.6);
}
#center-toast.bail { border-left-color: var(--orange); color: var(--orange); }
#center-toast span small { display: block; font: 500 10px/1.4 var(--mono); letter-spacing: 3px; color: var(--muted); margin-top: 4px; }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -50%) scale(1.15) skew(-6deg); } }

#balance-wrap {
  position: absolute;
  left: 50%;
  bottom: max(36px, calc(22px + env(safe-area-inset-bottom)));
  transform: translateX(-50%);
  width: min(320px, 44vw);
  padding: 8px 12px 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.balance-label { display: flex; justify-content: space-between; margin-bottom: 6px; }
.balance-label span { font: 600 8px/1 var(--mono); letter-spacing: 2.4px; color: var(--muted); }
.balance-label em { font: 800 9px/1 var(--mono); letter-spacing: 1.4px; color: var(--acid); font-style: normal; }
#balance-track { position: relative; height: 8px; background: rgba(255,255,255,0.12); overflow: hidden; }
.balance-safe { position: absolute; left: 25%; right: 25%; top: 0; bottom: 0; border-left: 1px solid rgba(215,255,63,0.5); border-right: 1px solid rgba(215,255,63,0.5); }
#balance-marker {
  position: absolute;
  top: -2px;
  left: 50%;
  width: 4px;
  height: 12px;
  background: var(--paper);
  box-shadow: 0 0 8px rgba(255,255,255,0.7);
  transform: translateX(-50%);
}
#balance-marker.warn { background: var(--orange); box-shadow: 0 0 10px rgba(255,90,31,0.8); }

#speedo {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(24px, calc(14px + env(safe-area-inset-bottom)));
  width: 126px;
  text-align: right;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.5));
}
.speedo-copy { display: flex; align-items: baseline; justify-content: flex-end; gap: 4px; }
.speedo-copy span { font: 600 8px/1 var(--mono); letter-spacing: 2px; color: var(--muted); }
.speedo-copy b { font: 900 28px/1 var(--display); letter-spacing: -1px; font-variant-numeric: tabular-nums; }
.speedo-copy em { font: 600 8px/1 var(--mono); color: var(--muted); font-style: normal; }
#speed-bar { height: 3px; margin-top: 5px; background: rgba(255,255,255,0.14); }
#speed-bar b { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--acid), var(--orange)); transition: width 100ms linear; }

#pad-badge {
  position: absolute;
  left: 50%;
  bottom: max(16px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border: 1px solid var(--line);
  background: rgba(12,11,9,0.55);
  font: 700 8px/1 var(--mono);
  letter-spacing: 2px;
  color: var(--muted);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
#pad-badge i { width: 6px; height: 6px; border-radius: 50%; background: var(--acid); box-shadow: 0 0 8px var(--acid); }

/* ============================================================ TOUCH CONTROLS */

#touch-controls { display: none; }

body.touch #touch-controls {
  display: flex;
  position: absolute;
  inset: 0;
  z-index: 12;
  pointer-events: none;
  padding: 0 max(14px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(14px, env(safe-area-inset-left));
  align-items: flex-end;
  justify-content: space-between;
}
body.touch #speedo { bottom: auto; top: 50%; right: 10px; transform: translateY(-50%); width: 74px; }
body.touch #speedo .speedo-copy b { font-size: 21px; }
body.touch #speedo .speedo-copy span { display: none; }
body.touch #hud-best { display: none; }
body.touch #pad-badge { display: none !important; }

#stick-zone {
  pointer-events: auto;
  width: clamp(120px, 30vw, 156px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  touch-action: none;
}
#stick-base {
  position: relative;
  width: clamp(108px, 27vw, 142px);
  height: clamp(108px, 27vw, 142px);
  border-radius: 50%;
  border: 1.5px solid rgba(244, 240, 230, 0.26);
  background:
    radial-gradient(circle at 50% 50%, rgba(244,240,230,0.08) 0 32%, rgba(12,11,9,0.25) 33% 100%);
  box-shadow: inset 0 0 24px rgba(0,0,0,0.3), 0 6px 24px rgba(0,0,0,0.2);
  touch-action: none;
}
#stick-base::before, #stick-base::after {
  content: "";
  position: absolute;
  background: rgba(244,240,230,0.12);
}
#stick-base::before { left: 12%; right: 12%; top: 50%; height: 1px; }
#stick-base::after { top: 12%; bottom: 12%; left: 50%; width: 1px; }
#stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44%;
  height: 44%;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 40% 34%, rgba(244,240,230,0.9), rgba(190,183,170,0.7) 45%, rgba(70,66,60,0.9));
  border: 1px solid rgba(255,255,255,0.4);
  box-shadow: 0 4px 14px rgba(0,0,0,0.5), inset 0 -4px 10px rgba(0,0,0,0.3);
  transition: transform 60ms linear;
}
#stick-zone.active #stick-knob { background: radial-gradient(circle at 40% 34%, #fff, var(--orange-soft) 45%, var(--orange)); }

#touch-right {
  pointer-events: auto;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  touch-action: none;
}

.touch-label {
  font: 700 7px/1 var(--mono);
  letter-spacing: 1.8px;
  color: rgba(244,240,230,0.5);
  text-align: center;
  white-space: nowrap;
}

#trick-zone { display: flex; flex-direction: column; align-items: center; gap: 4px; }
#trick-pad {
  position: relative;
  width: clamp(112px, 29vw, 146px);
  height: clamp(112px, 29vw, 146px);
  border-radius: 50%;
  border: 1.5px dashed rgba(215, 255, 63, 0.55);
  background:
    radial-gradient(circle at 50% 50%, rgba(215,255,63,0.12) 0 40%, rgba(12,11,9,0.3) 41% 100%);
  box-shadow: inset 0 0 26px rgba(215,255,63,0.08), 0 6px 24px rgba(0,0,0,0.2);
  touch-action: none;
  transition: transform 90ms ease, border-color 90ms ease;
}
#trick-pad.active { transform: scale(1.04); border-color: var(--acid); border-style: solid; }
.pad-arrow {
  position: absolute;
  font: 800 10px/1 var(--mono);
  color: rgba(244,240,230,0.35);
  transition: color 90ms ease;
}
.pad-arrow.up { top: 8px; left: 50%; transform: translateX(-50%); }
.pad-arrow.down { bottom: 8px; left: 50%; transform: translateX(-50%); }
.pad-arrow.left { left: 9px; top: 50%; transform: translateY(-50%); }
.pad-arrow.right { right: 9px; top: 50%; transform: translateY(-50%); }
#trick-pad.active .pad-arrow { color: rgba(215,255,63,0.7); }
.pad-core {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  pointer-events: none;
}
.pad-core strong { font: 900 13px/1 var(--display); letter-spacing: 0.5px; }
.pad-core span { font: 700 7px/1 var(--mono); letter-spacing: 2px; color: var(--acid); }

.touch-action {
  -webkit-appearance: none;
  appearance: none;
  width: clamp(58px, 15vw, 70px);
  height: clamp(58px, 15vw, 70px);
  border-radius: 50%;
  border: 1.5px solid rgba(244,240,230,0.28);
  background: rgba(12,11,9,0.42);
  color: var(--paper);
  font: 900 11px/1 var(--display);
  letter-spacing: 0.5px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  touch-action: none;
  transition: transform 80ms ease, background 80ms ease, border-color 80ms ease;
}
.touch-action span { font: 600 6px/1 var(--mono); letter-spacing: 1.4px; color: var(--muted); }
.touch-action.active { transform: scale(0.94); background: rgba(255,90,31,0.4); border-color: var(--orange); }
.touch-action.active span { color: var(--paper); }

/* ============================================================ OVERLAYS */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  background:
    radial-gradient(ellipse at 70% 40%, transparent 0%, rgba(8,7,6,0.35) 75%),
    linear-gradient(100deg, rgba(8,7,6,0.94) 0%, rgba(8,7,6,0.82) 38%, rgba(8,7,6,0.42) 70%, rgba(8,7,6,0.55) 100%);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
  animation: fadeIn 260ms ease both;
}
@keyframes fadeIn { from { opacity: 0; } }

.start-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    repeating-linear-gradient(115deg, transparent 0 58px, rgba(255,90,31,0.035) 58px 59px, transparent 59px 118px),
    linear-gradient(to top, rgba(8,7,6,0.85), transparent 45%);
}
.start-inner {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(24px, 6vw, 90px);
  width: 100%;
  max-width: 1380px;
  margin: auto;
  padding: clamp(20px, 4vw, 54px) clamp(22px, 5vw, 72px) 70px;
}

.start-main { flex: 1 1 auto; min-width: 0; max-width: 660px; }
.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  font: 600 9px/1 var(--mono);
  letter-spacing: 2.6px;
  color: var(--muted);
  margin-bottom: 18px;
}
.eyebrow i { width: 22px; height: 2px; background: var(--orange); display: inline-block; }
.eyebrow b { color: var(--paper); }

#start-screen h1 {
  margin: 0;
  font: 900 clamp(58px, 11vw, 148px)/0.78 var(--display);
  letter-spacing: -0.075em;
  text-transform: uppercase;
  text-shadow: 0 16px 50px rgba(0,0,0,0.6);
  transform: skew(-3deg) rotate(-1.5deg);
  transform-origin: left center;
}
#start-screen h1 span { color: var(--orange); font-size: 0.52em; letter-spacing: -0.02em; vertical-align: 0.13em; }
.tagline {
  margin: 22px 0 0;
  font: 500 clamp(14px, 1.7vw, 19px)/1.4 var(--body);
  color: rgba(244,240,230,0.72);
  letter-spacing: 0.3px;
}
.tagline em { color: var(--acid); font-style: normal; font-weight: 700; }

.start-actions { display: flex; align-items: center; gap: 22px; margin-top: clamp(26px, 4vh, 38px); }
#start-btn {
  -webkit-appearance: none;
  appearance: none;
  border: 0;
  background: var(--orange);
  color: var(--ink);
  font: 900 clamp(20px, 2.2vw, 30px)/1 var(--display);
  letter-spacing: 1px;
  padding: 20px 46px 18px;
