  transform: skew(-7deg);
  box-shadow: 6px 6px 0 rgba(244,240,230,0.95), 0 14px 44px rgba(255,90,31,0.3);
  transition: transform 120ms ease, box-shadow 120ms ease, background 120ms ease;
}
#start-btn:hover { background: var(--acid); transform: skew(-7deg) translate(-1px, -1px); box-shadow: 8px 8px 0 rgba(244,240,230,0.95), 0 18px 54px rgba(215,255,63,0.25); }
#start-btn:active { transform: skew(-7deg) translate(3px, 3px); box-shadow: 2px 2px 0 rgba(244,240,230,0.95); }
.start-meta { display: flex; flex-direction: column; gap: 5px; max-width: 210px; }
.start-meta strong { font: 700 10px/1 var(--mono); letter-spacing: 2px; color: var(--paper); }
.start-meta span { font: 400 11px/1.45 var(--body); color: var(--muted); }

.start-badges { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin-top: clamp(26px, 4vh, 38px); }
.badge {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid var(--line);
