}
.badge .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 9px var(--cyan); }
.pad-status { font: 500 8px/1.3 var(--mono); letter-spacing: 1.2px; color: rgba(244,240,230,0.36); }
.pad-status.on { color: var(--acid); text-shadow: 0 0 12px rgba(215,255,63,0.4); }
.high-score { margin-top: 16px; font: 600 9px/1 var(--mono); letter-spacing: 2px; color: rgba(244,240,230,0.38); }
.high-score b { color: var(--paper); font-size: 11px; margin-left: 6px; }

.start-side {
  flex: 0 1 360px;
  padding: 26px 26px 22px;
