.ctrl-icon {
  flex: 0 0 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(244,240,230,0.18);
  font: 700 13px/1 var(--mono);
  color: var(--acid);
  background: rgba(255,255,255,0.03);
}
.control-row strong { display: block; font: 800 9px/1 var(--mono); letter-spacing: 1.8px; margin-bottom: 4px; }
.control-row span { display: block; font: 400 11px/1.4 var(--body); color: var(--muted); }
.side-note { margin-top: 16px; padding-top: 14px; border-top: 1px solid rgba(244,240,230,0.08); font: 400 10px/1.5 var(--body); color: var(--muted); }
.side-note b { color: var(--acid); letter-spacing: 3px; }

.start-footer {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 14px clamp(22px, 5vw, 72px) max(14px, env(safe-area-inset-bottom));
  border-top: 1px solid rgba(244,240,230,0.1);
  background: rgba(8,7,6,0.55);
  font: 600 8px/1 var(--mono);
  letter-spacing: 2px;
  color: rgba(244,240,230,0.32);
}
.start-footer b { margin-left: auto; color: var(--orange); }

/* pause */
#pause-screen { align-items: center; justify-content: center; background: rgba(7,6,5,0.76); }
.pause-card,
.results-card {
  position: relative;
  width: min(480px, calc(100vw - 40px));
  padding: clamp(26px, 4vw, 40px);
  background: rgba(15,14,12,0.94);
  border: 1px solid var(--line);
  border-top: 3px solid var(--orange);
  box-shadow: 0 40px 100px rgba(0,0,0,0.55);
  animation: cardIn 220ms cubic-bezier(.2,.9,.3,1.1) both;
}
@keyframes cardIn { from { transform: translateY(16px) scale(0.97); opacity: 0; } }
.pause-card h2,
.results-card h2 { margin: 0 0 20px; font: 900 clamp(32px, 5vw, 48px)/0.9 var(--display); letter-spacing: -2px; }
.pause-stats { display: flex; gap: 26px; margin-bottom: 26px; }
.pause-stats div { display: flex; flex-direction: column; gap: 5px; }
.pause-stats span { font: 600 8px/1 var(--mono); letter-spacing: 2px; color: var(--muted); }
.pause-stats b { font: 900 30px/1 var(--display); font-variant-numeric: tabular-nums; }

.big-btn {
  -webkit-appearance: none;
  appearance: none;
  border: 0;
  background: var(--orange);
  color: var(--ink);
  font: 900 18px/1 var(--display);
  letter-spacing: 1.5px;
  padding: 17px 32px 15px;
  cursor: pointer;
  transform: skew(-6deg);
  box-shadow: 4px 4px 0 rgba(244,240,230,0.9);
  transition: transform 110ms ease, background 110ms ease, box-shadow 110ms ease;
}
.big-btn:hover { background: var(--acid); transform: skew(-6deg) translate(-1px,-1px); box-shadow: 6px 6px 0 rgba(244,240,230,0.9); }
.big-btn:active { transform: skew(-6deg) translate(2px,2px); box-shadow: 1px 1px 0 rgba(244,240,230,0.9); }
.text-btn {
  -webkit-appearance: none;
  appearance: none;
  background: none;
  border: 0;
  color: var(--muted);
  font: 600 9px/1 var(--mono);
  letter-spacing: 2px;
  padding: 14px 2px 6px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 4px;
}
.text-btn:hover { color: var(--paper); }
.tiny { margin: 18px 0 0; font: 400 10px/1.4 var(--body); color: rgba(244,240,230,0.3); }
#pause-screen .big-btn { display: block; width: 100%; }

/* results */
#results-screen { align-items: center; justify-content: center; background: rgba(7,6,5,0.78); }
.results-card { width: min(560px, calc(100vw - 32px)); }
.results-card h2 { color: var(--acid); }
