.new-best { margin-bottom: 18px; padding: 9px 12px; background: var(--acid); color: var(--ink); font: 900 11px/1 var(--mono); letter-spacing: 2px; text-align: center; animation: pulse 1.4s infinite; }
.result-actions { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }

#rotate-hint {
  display: none;
  position: absolute;
  z-index: 40;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  padding: 7px 12px;
  background: rgba(10,9,8,0.8);
  border: 1px solid var(--line);
  font: 600 7px/1 var(--mono);
  letter-spacing: 1.4px;
  color: var(--muted);
