  .eyebrow { margin-bottom: 10px; }
  .tagline { margin-top: 12px; font-size: 13px; }
  .start-actions { margin-top: 16px; }
  .start-badges { margin-top: 14px; }
  .start-footer { padding-top: 8px; padding-bottom: 8px; }
  .start-side { max-height: 70vh; overflow: hidden; }
