  // ledge grind line (the box was built above)
  rails.push({
    ax: 13.1, az: 17, bx: 22.9, bz: 17, y: 0.655, length: 9.8, width: 0.9, ledge: true,
  });

  // funbox coping grind lines
  rails.push({ ax: funbox.x - funbox.halfX, az: funbox.z - funbox.halfZ, bx: funbox.x + funbox.halfX, bz: funbox.z - funbox.halfZ, y: funbox.h + 0.06, length: funbox.halfX * 2, width: 0.7, ledge: true });
  rails.push({ ax: funbox.x - funbox.halfX, az: funbox.z + funbox.halfZ, bx: funbox.x + funbox.halfX, bz: funbox.z + funbox.halfZ, y: funbox.h + 0.06, length: funbox.halfX * 2, width: 0.7, ledge: true });

  // launch lips
  const launchPads = [
    { ax: -17, az: -26.2, bx: 17, bz: -26.2, nx: 0, nz: -1, y: 4.4, type: 'quarter' },
    { ax: -11, az: 26.2, bx: 11, bz: 26.2, nx: 0, nz: 1, y: 3.7, type: 'quarter' },
    { ax: -36.2, az: -12, bx: -36.2, bz: 12, nx: -1, nz: 0, y: 4.1, type: 'quarter' },
    { ax: 36.2, az: -13, bx: 36.2, bz: 13, nx: 1, nz: 0, y: 3.8, type: 'quarter' },
  ];
  for (const k of kickers) {
    launchPads.push({
      ax: k.x1, az: k.zLip, bx: k.x2, bz: k.zLip,
      nx: 0, nz: k.flip ? 1 : -1, y: k.h, type: 'kicker',
    });
  }

  // SKATE letters
  const letterDefs = [
    { ch: 'S', x: 17, z: -22.5, up: 1.15 },
    { ch: 'K', x: -1, z: 3, up: 1.55 },
    { ch: 'A', x: -30.6, z: 6, up: 1.15 },
    { ch: 'T', x: 18, z: -5.1, up: 1.25 },
    { ch: 'E', x: -8, z: -15, up: 1.2 },
  ];
  const letters = [];
  const ringMat = new THREE.MeshStandardMaterial({ color: 0xd7ff3f, emissive: 0x6f8f00, emissiveIntensity: 0.9, metalness: 0.2, roughness: 0.35 });
  for (const def of letterDefs) {
    const group = new THREE.Group();
    const y = heightAt(def.x, def.z) + def.up;
    group.position.set(def.x, y, def.z);

    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: letterTexture(def.ch), transparent: true, depthWrite: false, toneMapped: false,
    }));
    sprite.scale.set(1.55, 1.55, 1);
    group.add(sprite);

    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.86, 0.045, 8, 32), ringMat);
    ring.rotation.x = Math.PI / 2;
    group.add(ring);

    const inner = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.012, 6, 24), new THREE.MeshBasicMaterial({ color: 0xff5a1f, transparent: true, opacity: 0.8 }));
    inner.rotation.x = Math.PI / 2;
    group.add(inner);

    scene.add(group);
    letters.push({ ...def, group, sprite, ring, inner, y, collected: false, phase: Math.random() * Math.PI * 2 });
  }

  // lights
  const hemi = new THREE.HemisphereLight(0xbfd6ff, 0x55483a, 0.85);
  scene.add(hemi);

  const sun = new THREE.DirectionalLight(0xffd2a1, 2.6);
  sun.position.set(-34, 44, -22);
  sun.target.position.set(0, 0, 2);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -48;
  sun.shadow.camera.right = 48;
  sun.shadow.camera.top = 48;
  sun.shadow.camera.bottom = -48;
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 130;
  sun.shadow.bias = -0.0005;
  sun.shadow.normalBias = 0.022;
  scene.add(sun);
  scene.add(sun.target);

  const fill = new THREE.DirectionalLight(0x7ba7d8, 0.55);
  fill.position.set(30, 22, 26);
  scene.add(fill);

  const rim = new THREE.DirectionalLight(0xff7a3a, 0.5);
  rim.position.set(-20, 9, 30);
  scene.add(rim);

  scene.fog = new THREE.Fog(0xd9c4ab, 68, 220);

  const sunHelper = null;

  function update(dt, elapsed) {
    for (const l of letters) {
      if (l.collected) continue;
      l.group.position.y = l.y + Math.sin(elapsed * 2.1 + l.phase) * 0.18;
      l.group.rotation.y = elapsed * 1.35 + l.phase;
      l.ring.rotation.z = elapsed * 1.9;
      const s = 1 + Math.sin(elapsed * 3.4 + l.phase) * 0.035;
      l.sprite.scale.set(1.55 * s, 1.55 * s, 1);
    }
  }

  return {
    heightAt,
    rails,
    launchPads,
    letters,
    update,
    sun,
    spawn: PARK.spawn,
    pillars: [
      { x: -30, z: -21 }, { x: 30, z: -21 }, { x: -30, z: 21 }, { x: 30, z: 21 },
    ],
  };
}

import * as THREE from '../vendor/three.module.js';

/* ------------------------------------------------------------------ *
 * Stylised low-poly skater with a board rig that can flip, shuv, spin
 * and tumble. Everything is primitives so it loads instantly.
 * ------------------------------------------------------------------ */

const SKIN = 0xb97c52;
const SKIN_DARK = 0x9c633f;
const HOODIE = 0xff5a1f;
const HOODIE_DARK = 0xd3430e;
const PANTS = 0x23262c;
const SHOE = 0xf1ece0;
const SHOE_SOLE = 0xcfc7b7;
const METAL = 0xb8bbbe;
const DECK = 0x24211d;
const GRIP = 0x171512;
const BEANIE = 0x1a2a33;
const WHEEL = 0xe8dfcd;

function mat(color, opts = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: opts.roughness ?? 0.8, metalness: opts.metalness ?? 0, ...opts });
}

function limb(length, radius, material, segments = 8) {
  const group = new THREE.Group();
  const geo = new THREE.CapsuleGeometry(radius, Math.max(0.01, length - radius * 2), 3, segments);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.y = -length / 2;
  mesh.castShadow = true;
  group.add(mesh);
  const joint = new THREE.Mesh(new THREE.SphereGeometry(radius * 0.95, 8, 6), material);
  joint.castShadow = true;
  group.add(joint);
  return { group, mesh, length };
}

function roundedDeckShape(width = 0.78, length = 1.92) {
  const w = width / 2, l = length / 2;
  const s = new THREE.Shape();
  s.moveTo(-w + 0.03, -l + 0.12);
  s.quadraticCurveTo(-w, -l + 0.03, -w + 0.11, -l + 0.01);
  s.lineTo(w - 0.11, -l + 0.01);
  s.quadraticCurveTo(w, -l + 0.03, w - 0.03, -l + 0.12);
  s.lineTo(w + 0.015, -0.5);
  s.quadraticCurveTo(w - 0.01, -0.38, w, -0.28);
  s.lineTo(w, 0.28);
  s.quadraticCurveTo(w - 0.01, 0.38, w + 0.015, 0.5);
  s.lineTo(w - 0.03, l - 0.12);
  s.quadraticCurveTo(w, l - 0.03, w - 0.11, l - 0.01);
  s.lineTo(-w + 0.11, l - 0.01);
  s.quadraticCurveTo(-w, l - 0.03, -w + 0.03, l - 0.12);
  s.lineTo(-w - 0.015, 0.5);
  s.quadraticCurveTo(-w + 0.01, 0.38, -w, 0.28);
  s.lineTo(-w, -0.28);
  s.quadraticCurveTo(-w + 0.01, -0.38, -w - 0.015, -0.5);
  s.closePath();
  return s;
}

export class Skater {
  constructor(scene) {
    this.scene = scene;
    this.group = new THREE.Group();
    this.tilt = new THREE.Group();
    this.group.add(this.tilt);

    this.boardGroup = new THREE.Group();
    this.boardGroup.position.y = 0.16;
    this.tilt.add(this.boardGroup);

    this.body = new THREE.Group();
    this.tilt.add(this.body);

    this.activeTrick = null;
    this.trickT = 0;
    this.trickDur = 0.58;
    this.wheelSpin = 0;
    this.bob = 0;

    this._buildBoard();
    this._buildBody();

    this.group.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = false; } });
    scene.add(this.group);
    this.group.visible = false;
  }

  _buildBoard() {
    const g = this.boardGroup;

    const deckShape = roundedDeckShape();
    const deckGeo = new THREE.ExtrudeGeometry(deckShape, {
      depth: 0.055, bevelEnabled: true, bevelSize: 0.025, bevelThickness: 0.018, bevelSegments: 2, curveSegments: 7,
    });
    deckGeo.rotateX(-Math.PI / 2);
    const deckMat = new THREE.MeshStandardMaterial({ color: DECK, roughness: 0.6 });
    const deck = new THREE.Mesh(deckGeo, deckMat);
    deck.position.y = 0.015;
    g.add(deck);

    // grip tape top
    const gripGeo = new THREE.ShapeGeometry(roundedDeckShape(0.73, 1.84), 6);
    gripGeo.rotateX(-Math.PI / 2);
    const grip = new THREE.Mesh(gripGeo, new THREE.MeshStandardMaterial({ color: GRIP, roughness: 1 }));
    grip.position.y = 0.082;
    g.add(grip);

    // underside graphic
    const bottomGeo = new THREE.ShapeGeometry(roundedDeckShape(0.68, 1.78), 5);
    bottomGeo.rotateX(Math.PI / 2);
    const bottom = new THREE.Mesh(bottomGeo, new THREE.MeshStandardMaterial({ color: 0xff5a1f, roughness: 0.7, side: THREE.DoubleSide }));
    bottom.position.y = -0.005;
    g.add(bottom);

    // nose/tail kick
    for (const side of [-1, 1]) {
      const kick = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.025, 0.34), deckMat);
      kick.position.set(0, 0.085, side * 0.82);
      kick.rotation.x = side * 0.2;
      g.add(kick);
    }

    // trucks
    for (const z of [-0.62, 0.62]) {
      const truck = new THREE.Group();
      const base = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.035, 0.22), mat(METAL, { metalness: 0.85, roughness: 0.3 }));
      base.position.y = -0.015;
      truck.add(base);
      const hanger = new THREE.Mesh(new THREE.BoxGeometry(0.56, 0.05, 0.12), mat(0x9a9da1, { metalness: 0.8, roughness: 0.35 }));
      hanger.position.y = -0.065;
      truck.add(hanger);
      const axle = new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.026, 0.76, 6), mat(0xcfd2d4, { metalness: 0.9, roughness: 0.25 }));
      axle.rotation.z = Math.PI / 2;
      axle.position.y = -0.075;
      truck.add(axle);
      truck.position.z = z;
      g.add(truck);
    }

    // wheels
    this.wheels = [];
    for (const z of [-0.62, 0.62]) {
      for (const x of [-0.35, 0.35]) {
        const w = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.1, 0.08, 12), mat(WHEEL, { roughness: 0.55 }));
        w.rotation.z = Math.PI / 2;
        w.position.set(x, -0.075, z);
        g.add(w);
        this.wheels.push(w);
        const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.085, 8), mat(0x6e6a62, { metalness: 0.5, roughness: 0.4 }));
        hub.rotation.z = Math.PI / 2;
        hub.position.set(x, -0.075, z);
        g.add(hub);
      }
    }
  }

  _buildBody() {
    const b = this.body;

    const pants = mat(PANTS, { roughness: 0.9 });
    const shoe = mat(SHOE, { roughness: 0.68 });
    const hoodie = mat(HOODIE, { roughness: 0.85 });
    const hoodieDark = mat(HOODIE_DARK, { roughness: 0.9 });
    const skin = mat(SKIN, { roughness: 0.85 });
    const beanie = mat(BEANIE, { roughness: 0.95 });

    // pelvis
    const pelvis = new THREE.Mesh(new THREE.CapsuleGeometry(0.19, 0.16, 3, 8), pants);
    pelvis.rotation.z = Math.PI / 2;
    pelvis.position.set(0, 0.92, 0);
    pelvis.castShadow = true;
    b.add(pelvis);

    // torso / hoodie
    const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.235, 0.28, 4, 9), hoodie);
    torso.position.set(0, 1.33, 0);
    torso.castShadow = true;
    b.add(torso);

    const hood = new THREE.Mesh(new THREE.TorusGeometry(0.17, 0.055, 6, 12), hoodieDark);
    hood.position.set(0, 1.53, -0.04);
    hood.rotation.x = Math.PI / 2;
    b.add(hood);

    // zipper + chest slash
    const zip = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.4, 0.02), mat(0xb9b4a9));
    zip.position.set(0, 1.31, 0.225);
    b.add(zip);
    const slash = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.06, 0.012), mat(0xd7ff3f, { roughness: 0.6 }));
    slash.position.set(0.08, 1.4, 0.245);
    slash.rotation.z = -0.45;
    b.add(slash);

    // neck + head
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.09, 0.1, 7), skin);
    neck.position.set(0, 1.6, 0);
    b.add(neck);

    const head = new THREE.Mesh(new THREE.SphereGeometry(0.165, 12, 10), skin);
    head.position.set(0, 1.76, 0);
    head.scale.set(0.92, 1.05, 0.95);
    head.castShadow = true;
    b.add(head);

    // beanie
    const cap = new THREE.Mesh(new THREE.SphereGeometry(0.172, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.58), beanie);
    cap.position.set(0, 1.79, 0);
    cap.scale.set(1.02, 0.95, 1.02);
    b.add(cap);
    const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.178, 0.178, 0.06, 12), beanie);
    brim.position.set(0, 1.78, 0);
    b.add(brim);

    // glasses
    const glasses = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.045, 0.05), mat(0x111214, { roughness: 0.25, metalness: 0.2 }));
    glasses.position.set(0, 1.77, 0.15);
    b.add(glasses);

    // backpack
    const pack = new THREE.Mesh(new THREE.BoxGeometry(0.36, 0.42, 0.17), mat(0x2f3b3f, { roughness: 0.95 }));
    pack.position.set(0, 1.3, -0.26);
    pack.castShadow = true;
    b.add(pack);
    const strap = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.36, 0.02), mat(0x191c1e));
    strap.position.set(0.14, 1.34, 0.24);
    b.add(strap);

    // legs (front foot towards +z)
    this.legs = [];
    for (const side of [-1, 1]) {
      const hip = new THREE.Group();
      hip.position.set(side * 0.155, 0.9, side * 0.29);
      const upper = limb(0.4, 0.085, pants);
      upper.group.rotation.x = -0.12;
      hip.add(upper.group);

      const knee = new THREE.Group();
      knee.position.y = -0.4;
      upper.group.add(knee);
      const lower = limb(0.38, 0.072, pants);
      lower.group.rotation.x = 0.28;
      knee.add(lower.group);

      const ankle = new THREE.Group();
      ankle.position.y = -0.38;
      lower.group.add(ankle);

      const shoeMesh = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.105, 0.35), shoe);
      shoeMesh.position.set(0, 0.045, 0.07);
      shoeMesh.castShadow = true;
      ankle.add(shoeMesh);
      const sole = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.035, 0.37), mat(SHOE_SOLE, { roughness: 0.9 }));
      sole.position.set(0, -0.015, 0.07);
      ankle.add(sole);

      b.add(hip);
      this.legs.push({ hip, upper, knee, lower, ankle, side });
    }

    // arms
    this.arms = [];
    for (const side of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(side * 0.29, 1.48, 0);
      const upper = limb(0.32, 0.068, hoodie);
      upper.group.rotation.z = side * 0.15;
      shoulder.add(upper.group);

      const elbow = new THREE.Group();
      elbow.position.y = -0.32;
      upper.group.add(elbow);
      const lower = limb(0.3, 0.056, hoodieDark);
      lower.group.rotation.x = 0.18;
      elbow.add(lower.group);

      const hand = new THREE.Mesh(new THREE.SphereGeometry(0.062, 8, 6), skin);
      hand.position.y = -0.3;
      hand.castShadow = true;
      lower.group.add(hand);

      b.add(shoulder);
      this.arms.push({ shoulder, upper, elbow, lower, hand, side });
    }
  }

  playTrick(def) {
    this.activeTrick = def;
    this.trickT = 0;
    this.trickDur = def.dur || 0.58;
  }

  clearTrick() {
    this.activeTrick = null;
    this.trickT = 0;
    this.boardGroup.rotation.set(0, 0, 0);
    this.boardGroup.position.y = 0.16;
  }

  show() { this.group.visible = true; }

  reset(x, y, z, heading) {
    this.group.position.set(x, y, z);
    this.group.rotation.set(0, heading, 0);
    this.tilt.rotation.set(0, 0, 0);
    this.clearTrick();
    this.body.rotation.set(0, 0, 0);
    this.legs.forEach(l => {
      l.hip.position.y = 0.9;
      l.upper.group.rotation.x = -0.12;
      l.lower.group.rotation.x = 0.28;
    });
    this.arms.forEach(a => {
      a.shoulder.rotation.set(0, 0, a.side * 0.15);
      a.upper.group.rotation.set(0, 0, a.side * 0.15);
      a.elbow.rotation.x = 0.18;
    });
  }

  update(dt, s) {
    const g = this.group;
    g.position.set(s.x, s.y, s.z);
    g.rotation.y = s.heading;

    const speed = Math.abs(s.speed || 0);
    const air = s.air || 0;
    const crouch = s.crouch || 0;
    const lean = s.lean || 0;
    const grind = s.grinding ? 1 : 0;
    const manual = s.manual ? 1 : 0;
    const grab = s.grab ? 1 : 0;
    const bail = s.bail || 0;
    const charging = s.charging ? 1 : 0;

    this.bob += dt * (2 + speed * 0.55);

    // overall tilt: slope pitch, carving lean, grind balance
    const slopePitch = s.slopePitch || 0;
    const targetZ = s.slopeRoll || 0;
    const bal = s.balance || 0;
    if (bail > 0) {
      const t = s.bailTime || 0;
      this.tilt.rotation.x += (Math.sin(t * 10) * 0.35 - this.tilt.rotation.x) * Math.min(1, dt * 12);
      this.tilt.rotation.z += (Math.cos(t * 8) * 0.4 - this.tilt.rotation.z) * Math.min(1, dt * 12);
      this.tilt.rotation.y = Math.sin(t * 7) * 0.4;
    } else {
      this.tilt.rotation.x += (-slopePitch * 0.85 - this.tilt.rotation.x) * Math.min(1, dt * 10);
      this.tilt.rotation.z += (-lean * 0.17 + bal * 0.16 - this.tilt.rotation.z) * Math.min(1, dt * 9);
      this.tilt.rotation.y += (0 - this.tilt.rotation.y) * Math.min(1, dt * 9);
    }

    // body crouch + air pose
    const bodyBase = 0.92 - crouch * 0.16 - charging * 0.06 - (manual ? 0.02 : 0);
    const swing = Math.sin(this.bob) * 0.015 * Math.min(1, speed / 4);
    this.body.position.y = swing - air * 0.03;

    for (const leg of this.legs) {
      const back = leg.side > 0 ? 1 : -1;
      const stance = back * 0.16;
      leg.hip.position.y = bodyBase;
      leg.hip.position.z = leg.side * 0.29 + (manual ? 0.05 : 0);
      let upperX = -0.18 + crouch * 0.62 + air * 0.55 + (grab ? 0.35 : 0) + stance * 0.5;
      let lowerX = 0.34 + crouch * 0.82 + air * 0.85 + (grab ? 0.6 : 0) - stance * 0.2;
      if (grind) { upperX += 0.08; lowerX += 0.25; }
      if (manual) { upperX += -0.12; lowerX -= 0.2; }
      leg.upper.group.rotation.x += (upperX - leg.upper.group.rotation.x) * Math.min(1, dt * 14);
      leg.lower.group.rotation.x += (lowerX - leg.lower.group.rotation.x) * Math.min(1, dt * 14);
      leg.hip.rotation.z = leg.side * (0.04 + crouch * 0.07);
      leg.knee.rotation.z = leg.side * 0.04;
    }

    for (const arm of this.arms) {
      const side = arm.side;
      let sx = -0.12 - crouch * 0.25 + air * 0.9 + (manual ? -0.35 : 0);
      let sz = side * (0.2 + crouch * 0.2 + air * 0.45);
      let ex = 0.28 + crouch * 0.35 + air * 0.2;
      if (grab && side < 0) { sx = 1.15; sz = 0.28; ex = 0.15; }
      if (grind) { sx = -0.05; sz = side * 0.85; }
      if (bail > 0) { sx = -0.7 * Math.sin((s.bailTime || 0) * 9 + side); sz = side * 1.1; ex = 0.2; }
      arm.shoulder.rotation.x += (sx - arm.shoulder.rotation.x) * Math.min(1, dt * 9);
      arm.shoulder.rotation.z += (sz - arm.shoulder.rotation.z) * Math.min(1, dt * 9);
      arm.elbow.rotation.x += (ex - arm.elbow.rotation.x) * Math.min(1, dt * 12);
      arm.upper.group.rotation.z = side * 0.12;
    }

    // head looks into travel
    this.body.rotation.y += ((manual ? -0.18 : 0) - this.body.rotation.y) * Math.min(1, dt * 8);

    // board flip animation
    if (this.activeTrick) {
      this.trickT += dt;
      const p = Math.min(1, this.trickT / this.trickDur);
      const e = 1 - Math.pow(1 - p, 3);
      const d = this.activeTrick;
      this.boardGroup.rotation.z = THREE.MathUtils.degToRad(d.roll || 0) * e;
      this.boardGroup.rotation.y = THREE.MathUtils.degToRad(d.yaw || 0) * e;
      this.boardGroup.rotation.x = THREE.MathUtils.degToRad(d.pitch || 0) * e;
      this.boardGroup.position.y = 0.16 + Math.sin(p * Math.PI) * (d.pop || 0.1);
      if (p >= 1) {
        this.boardGroup.rotation.set(0, 0, 0);
        this.boardGroup.position.y = 0.16;
        this.activeTrick = null;
      }
    } else if (manual) {
      this.boardGroup.rotation.x += (-0.3 - this.boardGroup.rotation.x) * Math.min(1, dt * 8);
      this.boardGroup.rotation.y += (0 - this.boardGroup.rotation.y) * Math.min(1, dt * 8);
      this.boardGroup.rotation.z += (0 - this.boardGroup.rotation.z) * Math.min(1, dt * 8);
      this.boardGroup.position.y += (0.2 - this.boardGroup.position.y) * Math.min(1, dt * 8);
    } else {
      this.boardGroup.rotation.x += (0 - this.boardGroup.rotation.x) * Math.min(1, dt * 10);
      this.boardGroup.rotation.y += (0 - this.boardGroup.rotation.y) * Math.min(1, dt * 10);
      this.boardGroup.rotation.z += (0 - this.boardGroup.rotation.z) * Math.min(1, dt * 10);
      this.boardGroup.position.y += (0.16 - this.boardGroup.position.y) * Math.min(1, dt * 10);
    }

    // wheel spin
    this.wheelSpin += speed * dt * 7.5;
    for (const w of this.wheels) w.rotation.x = this.wheelSpin;
  }
}

/* ------------------------------------------------------------------ *
 * SKATE//SHIFT — input
 * Keyboard, touch (virtual stick + flick pad), and the Gamepad API.
 * USB-C and Bluetooth pads both appear through the same standard
 * mapping, so no driver-specific code is needed.
 * ------------------------------------------------------------------ */

export class Input {
  constructor() {
    this.moveX = 0;
    this.moveY = 0;
    this.flicks = [];
    this.jumpPressed = false;
    this.jumpReleased = false;
    this.jumpHeld = false;
    this.grab = false;
    this.boost = false;
    this.pausePressed = false;
    this.anyPressed = false;

    this.keys = new Set();
    this.keyVector = { x: 0, y: 0 };
    this.touchVector = { x: 0, y: 0 };
    this.padVector = { x: 0, y: 0 };

    this.padIndex = null;
    this.padName = '';
    this.padFlickArmed = true;
    this.padPrev = { x: 0, y: 0 };
    this.padButtonPrev = {};
    this.onPadChange = null;

    this.touch = false;
    this.stickPointer = null;
    this.stickCenter = { x: 0, y: 0 };
    this.stickRadius = 52;
    this.padPointer = null;
    this.padStart = { x: 0, y: 0, t: 0 };
    this.padFlicked = false;
    this.grabPointer = null;

    this._bindKeyboard();
    this._bindTouch();
    this._bindGamepad();
    this._bindLifecycle();
    this._detectTouch();
  }

  _detectTouch() {
    const coarse = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0;
    const narrow = window.innerWidth <= 820;
    this.touch = coarse || narrow;
    document.body.classList.toggle('touch', this.touch);
  }

  _bindLifecycle() {
    window.addEventListener('resize', () => this._detectTouch());
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.keyVector.x = this.keyVector.y = 0;
      this.jumpHeld = false;
      this.grab = false;
      this.touchVector.x = this.touchVector.y = 0;
      this._releaseStick();
      this._releaseGrab();
    });
    window.addEventListener('contextmenu', e => e.preventDefault());
  }

  _bindKeyboard() {
    const map = {
      KeyW: 'up', ArrowUp: 'up', KeyS: 'down', ArrowDown: 'down',
      KeyA: 'left', ArrowLeft: 'left', KeyD: 'right', ArrowRight: 'right',
    };
    window.addEventListener('keydown', e => {
      if (e.repeat) {
        if (['Space', 'KeyJ', 'KeyK', 'KeyL', 'KeyU', 'KeyI', 'KeyO', 'KeyM'].includes(e.code)) e.preventDefault();
        return;
      }
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.code)) e.preventDefault();
      this.keys.add(e.code);
      this.anyPressed = true;
      this._updateKeyVector();
      if (e.code === 'Space') { this.jumpPressed = true; this.jumpHeld = true; }
      if (e.code === 'KeyF') this.grab = true;
      if (e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.grab = true;
      if (e.code === 'KeyJ') this.flicks.push('left');
      if (e.code === 'KeyK') this.flicks.push('right');
      if (e.code === 'KeyL') this.flicks.push('upleft');
      if (e.code === 'KeyU') this.flicks.push('downright');
      if (e.code === 'KeyI') this.flicks.push('downleft');
      if (e.code === 'KeyO') this.flicks.push('upright');
      if (e.code === 'KeyM') this.flicks.push('down');
      if (e.code === 'Escape' || e.code === 'KeyP') this.pausePressed = true;
      if (e.code === 'KeyR') this.flicks.push('up');
      if (e.code === 'KeyB') this.boost = true;
    });
    window.addEventListener('keyup', e => {
      this.keys.delete(e.code);
      this._updateKeyVector();
      if (e.code === 'Space') { this.jumpReleased = true; this.jumpHeld = false; }
      if (e.code === 'KeyF' || e.code === 'ShiftLeft' || e.code === 'ShiftRight') this.grab = false;
      if (e.code === 'KeyB') this.boost = false;
    });
  }

  _updateKeyVector() {
    let x = 0, y = 0;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y += 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y -= 1;
    const m = Math.hypot(x, y) || 1;
    this.keyVector.x = x / m;
    this.keyVector.y = y / m;
    if (!x && !y) { this.keyVector.x = 0; this.keyVector.y = 0; }
  }

  _bindTouch() {
    const stickZone = document.getElementById('stick-zone');
    const stickBase = document.getElementById('stick-base');
    const knob = document.getElementById('stick-knob');
    if (!stickZone) return;

    const updateStick = (e) => {
      const dx = e.clientX - this.stickCenter.x;
      const dy = e.clientY - this.stickCenter.y;
      const dist = Math.hypot(dx, dy);
      const max = this.stickRadius;
      const clamped = Math.min(dist, max);
      const nx = dist > 0 ? (dx / dist) * (clamped / max) : 0;
      const ny = dist > 0 ? (dy / dist) * (clamped / max) : 0;
      this.touchVector.x = Math.abs(nx) > 0.12 ? nx : 0;
      this.touchVector.y = Math.abs(ny) > 0.12 ? -ny : 0;
      knob.style.transform = `translate(calc(-50% + ${nx * max * 0.62}px), calc(-50% + ${ny * max * 0.62}px))`;
    };

    stickZone.addEventListener('pointerdown', e => {
      e.preventDefault();
      if (this.stickPointer !== null) return;
      this.stickPointer = e.pointerId;
      stickZone.setPointerCapture?.(e.pointerId);
      const rect = stickBase.getBoundingClientRect();
      this.stickCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
      this.stickRadius = rect.width * 0.42;
      stickZone.classList.add('active');
      updateStick(e);
    });
    stickZone.addEventListener('pointermove', e => {
      if (e.pointerId !== this.stickPointer) return;
      e.preventDefault();
      updateStick(e);
    });
    const endStick = e => {
      if (e.pointerId !== this.stickPointer) return;
      this._releaseStick();
    };
    stickZone.addEventListener('pointerup', endStick);
    stickZone.addEventListener('pointercancel', endStick);
    stickZone.addEventListener('lostpointercapture', endStick);

    const trickPad = document.getElementById('trick-pad');
    const emit = (dir) => {
      this.flicks.push(dir);
      this.anyPressed = true;
      if (navigator.vibrate) navigator.vibrate(12);
    };
    const dirFrom = (dx, dy) => {
      const a = Math.atan2(-dy, dx) * 180 / Math.PI;
      if (a >= -22.5 && a < 22.5) return 'right';
      if (a >= 22.5 && a < 67.5) return 'upright';
      if (a >= 67.5 && a < 112.5) return 'up';
      if (a >= 112.5 && a < 157.5) return 'upleft';
      if (a >= 157.5 || a < -157.5) return 'left';
      if (a >= -157.5 && a < -112.5) return 'downleft';
      if (a >= -112.5 && a < -67.5) return 'down';
      return 'downright';
    };

    trickPad.addEventListener('pointerdown', e => {
      e.preventDefault();
      if (this.padPointer !== null) return;
      this.padPointer = e.pointerId;
      trickPad.setPointerCapture?.(e.pointerId);
      trickPad.classList.add('active');
      const rect = trickPad.getBoundingClientRect();
      this.padStart = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2, t: performance.now() };
      this.padFlicked = false;
    });
    trickPad.addEventListener('pointermove', e => {
      if (e.pointerId !== this.padPointer) return;
      e.preventDefault();
      if (this.padFlicked) return;
      const dx = e.clientX - this.padStart.x;
      const dy = e.clientY - this.padStart.y;
      if (Math.hypot(dx, dy) > 26) {
        emit(dirFrom(dx, dy));
        this.padFlicked = true;
      }
    });
    const endPad = e => {
      if (e.pointerId !== this.padPointer) return;
      if (!this.padFlicked) emit('up');
      this.padPointer = null;
      trickPad.classList.remove('active');
    };
    trickPad.addEventListener('pointerup', endPad);
    trickPad.addEventListener('pointercancel', e => {
      if (e.pointerId !== this.padPointer) return;
      this.padPointer = null;
      trickPad.classList.remove('active');
    });

    const grabBtn = document.getElementById('grab-btn');
    grabBtn.addEventListener('pointerdown', e => {
      e.preventDefault();
      this.grabPointer = e.pointerId;
      this.grab = true;
      grabBtn.classList.add('active');
      grabBtn.setPointerCapture?.(e.pointerId);
    });
    const endGrab = e => {
      if (e.pointerId !== this.grabPointer) return;
      this._releaseGrab();
    };
    grabBtn.addEventListener('pointerup', endGrab);
    grabBtn.addEventListener('pointercancel', endGrab);
    grabBtn.addEventListener('lostpointercapture', endGrab);

    // tapping the trick pad itself should work even if pointer captures odd
    trickPad.addEventListener('lostpointercapture', e => {
      if (e.pointerId === this.padPointer) {
        if (!this.padFlicked) emit('up');
        this.padPointer = null;
        trickPad.classList.remove('active');
      }
    });
  }

  _releaseStick() {
    this.stickPointer = null;
    this.touchVector.x = 0;
    this.touchVector.y = 0;
    document.getElementById('stick-zone')?.classList.remove('active');
    const knob = document.getElementById('stick-knob');
    if (knob) knob.style.transform = 'translate(-50%, -50%)';
  }

  _releaseGrab() {
    this.grabPointer = null;
    this.grab = false;
    document.getElementById('grab-btn')?.classList.remove('active');
  }

  _bindGamepad() {
    window.addEventListener('gamepadconnected', e => {
      this.padIndex = e.gamepad.index;
      this.padName = e.gamepad.id;
      this.onPadChange?.(true, this.padName);
    });
    window.addEventListener('gamepaddisconnected', e => {
      if (e.gamepad.index !== this.padIndex) return;
      this.padIndex = null;
      this.padName = '';
      this.padVector.x = this.padVector.y = 0;
      this.onPadChange?.(false, '');
    });
  }

  _pollGamepad() {
    if (this.padIndex === null) {
      const pads = navigator.getGamepads ? navigator.getGamepads() : [];
      for (const p of pads) {
        if (p && p.connected) {
          this.padIndex = p.index;
          this.padName = p.id;
          this.onPadChange?.(true, p.id);
          break;
        }
      }
    }
    if (this.padIndex === null) return;
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    const pad = pads[this.padIndex];
    if (!pad || !pad.connected) return;

    const dz = 0.16;
    const lx = Math.abs(pad.axes[0] || 0) > dz ? pad.axes[0] : 0;
    const ly = Math.abs(pad.axes[1] || 0) > dz ? pad.axes[1] : 0;
    this.padVector.x = lx;
    this.padVector.y = -ly;

    const rx = pad.axes[2] || 0;
    const ry = pad.axes[3] || 0;
    const mag = Math.hypot(rx, ry);
    if (mag > 0.72 && this.padFlickArmed) {
      const dir = directionFrom(rx, -ry);
      this.flicks.push(dir);
      this.anyPressed = true;
      this.padFlickArmed = false;
      if (navigator.vibrate) navigator.vibrate(10);
    }
    if (mag < 0.26) this.padFlickArmed = true;
    this.padPrev.x = rx;
    this.padPrev.y = ry;

    const pressed = i => !!pad.buttons[i]?.pressed;
    const edge = (i, key) => {
      const p = pressed(i);
      const prev = this.padButtonPrev[key] || false;
      this.padButtonPrev[key] = p;
      return p && !prev;
    };
    const released = (i, key) => {
      const p = pressed(i);
      const prev = this.padButtonPrev['r' + key] || false;
      this.padButtonPrev['r' + key] = p;
      return !p && prev;
    };

    if (edge(0, 'jump')) { this.jumpPressed = true; this.jumpHeld = true; this.anyPressed = true; }
    if (released(0, 'jump')) { this.jumpReleased = true; this.jumpHeld = false; }
    if (pressed(2) || pressed(5)) this.grab = true;
    else if (this.grabPointer === null) this.grab = false;
    if (pressed(7)) this.boost = true;
    else if (!this.keys.has('KeyB')) this.boost = false;
    if (edge(9, 'pause') || edge(8, 'pause2')) { this.pausePressed = true; this.anyPressed = true; }

    // D-pad trick shortcuts
    const dpad = [
      ['up', 12], ['down', 13], ['left', 14], ['right', 15],
    ];
    for (const [dir, idx] of dpad) {
      if (edge(idx, 'dpad' + idx)) { this.flicks.push(dir); this.anyPressed = true; }
    }
    // B = manual flick
    if (edge(1, 'b')) { this.flicks.push('down'); this.anyPressed = true; }
  }

  update(dt) {
    this._pollGamepad();
    let x = this.keyVector.x + this.touchVector.x + this.padVector.x;
    let y = this.keyVector.y + this.touchVector.y + this.padVector.y;
    const m = Math.hypot(x, y);
    if (m > 1) { x /= m; y /= m; }
    this.moveX = Math.abs(x) > 0.08 ? x : 0;
    this.moveY = Math.abs(y) > 0.08 ? y : 0;
  }

  endFrame() {
    this.flicks.length = 0;
    this.jumpPressed = false;
    this.jumpReleased = false;
    this.pausePressed = false;
    this.anyPressed = false;
  }

  rumble(strong = 0.5, weak = 0.2, ms = 90) {
    if (this.padIndex === null) return;
    const pad = navigator.getGamepads?.()[this.padIndex];
    const actuator = pad?.vibrationActuator;
    if (!actuator) return;
    try {
      actuator.playEffect('dual-rumble', {
        startDelay: 0, duration: ms, weakMagnitude: weak, strongMagnitude: strong,
      });
    } catch { /* unsupported pad */ }
  }
}

function directionFrom(x, y) {
  const a = Math.atan2(y, x) * 180 / Math.PI;
  if (a >= -22.5 && a < 22.5) return 'right';
  if (a >= 22.5 && a < 67.5) return 'upright';
  if (a >= 67.5 && a < 112.5) return 'up';
  if (a >= 112.5 && a < 157.5) return 'upleft';
  if (a >= 157.5 || a < -157.5) return 'left';
  if (a >= -157.5 && a < -112.5) return 'downleft';
  if (a >= -112.5 && a < -67.5) return 'down';
  return 'downright';
}

/* ------------------------------------------------------------------ *
 * SKATE//SHIFT — procedural audio
 * All sounds are synthesised with the Web Audio API: no downloads.
 * ------------------------------------------------------------------ */

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.rollGain = null;
    this.grindGain = null;
    this.started = false;
    this.noise = null;
  }

  ensure() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.75;
    this.master.connect(ctx.destination);

    // shared noise buffer
    const len = ctx.sampleRate * 2;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    this.noise = buf;

    // rolling wheels
    const roll = ctx.createBufferSource();
    roll.buffer = buf;
    roll.loop = true;
    const rollFilter = ctx.createBiquadFilter();
    rollFilter.type = 'lowpass';
    rollFilter.frequency.value = 520;
    rollFilter.Q.value = 1.2;
    this.rollGain = ctx.createGain();
    this.rollGain.gain.value = 0;
    roll.connect(rollFilter).connect(this.rollGain).connect(this.master);
    roll.start();

    // metal grind loop
    const grind = ctx.createBufferSource();
    grind.buffer = buf;
    grind.loop = true;
    const gf = ctx.createBiquadFilter();
    gf.type = 'bandpass';
    gf.frequency.value = 2600;
    gf.Q.value = 8;
    const g2 = ctx.createGain();
    g2.gain.value = 0;
    grind.connect(gf).connect(g2).connect(this.master);
    grind.start();
    this.grindGain = g2;
    this.grindFilter = gf;
    this.started = true;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.75, this.ctx.currentTime, 0.04);
  }

  _env(node, gain, attack, decay, peak) {
    const t = this.ctx.currentTime;
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(peak, t + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
  }

  _tone(freq, dur, type = 'sine', peak = 0.1, slide = 0, delay = 0) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t + dur);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(peak, t + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  _noise(dur, filterType, freq, peak = 0.1, q = 1, delay = 0, slideTo = 0) {
    if (!this.ctx || !this.noise) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = ctx.createBiquadFilter();
    filter.type = filterType;
    filter.frequency.setValueAtTime(freq, t);
    if (slideTo) filter.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
    filter.Q.value = q;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(peak, t + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.03);
  }

  updateRolling(speed, grounded, grinding) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const target = grounded && !grinding ? Math.min(0.09, 0.005 + speed * 0.006) : 0;
    this.rollGain.gain.setTargetAtTime(target, t, 0.1);
    if (this.grindGain) {
      this.grindGain.gain.setTargetAtTime(grinding ? 0.09 : 0, t, 0.04);
      this.grindFilter.frequency.setTargetAtTime(1800 + speed * 80, t, 0.1);
    }
  }

  push() {
    this._noise(0.16, 'bandpass', 700, 0.05, 0.7, 0, 1800);
    this._tone(95, 0.1, 'sine', 0.035, -30);
  }

  ollie(charged = 0) {
    this._noise(0.1, 'highpass', 1400, 0.09 + charged * 0.04, 0.7);
    this._tone(190 + charged * 40, 0.16, 'triangle', 0.06, 150);
    this._tone(68, 0.13, 'sine', 0.09, -20, 0.01);
  }

  land(impact = 1) {
    const p = Math.min(1, impact / 12);
    this._tone(52, 0.18, 'sine', 0.12 + p * 0.12, -18);
    this._noise(0.12, 'lowpass', 900, 0.08 + p * 0.08, 0.8);
    if (p > 0.5) this._noise(0.06, 'highpass', 2200, 0.05, 0.6, 0.02);
  }

  trick() {
    this._noise(0.15, 'bandpass', 1700, 0.05, 1.8, 0, 3200);
  }

  grindStart() {
    this._noise(0.22, 'bandpass', 3000, 0.08, 6);
    this._tone(720, 0.14, 'triangle', 0.03, 120);
  }

  bail() {
    this._noise(0.5, 'lowpass', 1200, 0.18, 0.8, 0, 180);
    this._tone(70, 0.42, 'sawtooth', 0.1, -40);
    this._tone(120, 0.25, 'square', 0.04, -60, 0.05);
  }

  pickup(letter = false) {
    const notes = letter ? [523, 659, 784, 1046] : [784, 1046];
    notes.forEach((n, i) => this._tone(n, 0.22, 'sine', letter ? 0.06 : 0.035, 0, i * 0.055));
  }

  tick() {
    this._tone(920, 0.06, 'square', 0.02);
  }

  end() {
    const notes = [392, 523, 659, 784];
    notes.forEach((n, i) => this._tone(n, 0.5, 'triangle', 0.06, 0, i * 0.13));
  }

  stopAll() {
    if (!this.ctx) return;
    this.rollGain?.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05);
    this.grindGain?.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05);
  }
}

import * as THREE from '../vendor/three.module.js';

/* Small sprite particle pools for dust, sparks and letter bursts. */

function radialTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)') {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(64, 64, 2, 64, 64, 62);
  grad.addColorStop(0, inner);
  grad.addColorStop(0.45, inner.replace('1)', '0.55)'));
  grad.addColorStop(1, outer);
  g.fillStyle = grad;
  g.beginPath();
  g.arc(64, 64, 63, 0, Math.PI * 2);
  g.fill();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function squareTexture(color) {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = color;
  g.fillRect(6, 6, 52, 52);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

class Pool {
  constructor(scene, texture, count, blending = THREE.NormalBlending) {
    this.items = [];
    for (let i = 0; i < count; i++) {
      const material = new THREE.SpriteMaterial({
        map: texture, transparent: true, opacity: 1, depthWrite: false,
        blending, toneMapped: false,
      });
      const sprite = new THREE.Sprite(material);
      sprite.visible = false;
      sprite.renderOrder = 5;
      scene.add(sprite);
      this.items.push({ sprite, material, life: 0, maxLife: 0, vel: new THREE.Vector3(), size: 0.2, gravity: 0, drag: 0.5 });
    }
    this.cursor = 0;
  }

  spawn(x, y, z, opts = {}) {
    const it = this.items[this.cursor];
    this.cursor = (this.cursor + 1) % this.items.length;
    it.sprite.visible = true;
    it.sprite.position.set(x, y, z);
    it.life = it.maxLife = opts.life || 0.5;
    it.vel.set(
      (Math.random() - 0.5) * (opts.spread || 3) + (opts.vx || 0),
      Math.random() * (opts.up || 2) + (opts.vy || 0),
      (Math.random() - 0.5) * (opts.spread || 3) + (opts.vz || 0)
    );
    it.size = opts.size || 0.5;
    it.gravity = opts.gravity ?? -3;
    it.drag = opts.drag ?? 1.5;
    it.material.color.set(opts.color || 0xffffff);
    it.material.opacity = opts.opacity ?? 0.8;
    it.sprite.scale.setScalar(it.size);
    it.baseOpacity = it.material.opacity;
  }

  update(dt) {
    for (const it of this.items) {
      if (!it.sprite.visible) continue;
      it.life -= dt;
      if (it.life <= 0) { it.sprite.visible = false; continue; }
      const damp = Math.exp(-it.drag * dt);
      it.vel.multiplyScalar(damp);
      it.vel.y += it.gravity * dt;
      it.sprite.position.addScaledVector(it.vel, dt);
      const t = it.life / it.maxLife;
      it.material.opacity = it.baseOpacity * Math.min(1, t * 1.8);
      it.sprite.scale.setScalar(it.size * (0.5 + (1 - t) * 1.3));
    }
  }
}

export class FX {
  constructor(scene) {
    this.dustTex = radialTexture('rgba(232,218,192,1)', 'rgba(232,218,192,0)');
    this.sparkTex = radialTexture('rgba(255,214,120,1)', 'rgba(255,140,40,0)');
    this.dust = new Pool(scene, this.dustTex, 70);
    this.sparks = new Pool(scene, this.sparkTex, 80, THREE.AdditiveBlending);
    this.letters = new Pool(scene, squareTexture('#d7ff3f'), 40);
  }

  land(x, y, z, power = 1) {
    const n = Math.round(4 + power * 5);
    for (let i = 0; i < n; i++) {
      this.dust.spawn(x + (Math.random() - 0.5) * 0.7, y + 0.08, z + (Math.random() - 0.5) * 0.7, {
        spread: 2.4 * power, up: 0.8 * power, size: 0.35 + Math.random() * 0.5,
        life: 0.45 + Math.random() * 0.35, opacity: 0.45, gravity: -1.2, drag: 2.4,
      });
    }
  }

  grindSparks(x, y, z, vx, vz) {
    for (let i = 0; i < 2; i++) {
      this.sparks.spawn(x + (Math.random() - 0.5) * 0.25, y + 0.03, z + (Math.random() - 0.5) * 0.25, {
        vx: -vx * 0.25 + (Math.random() - 0.5) * 2, vy: 0.7 + Math.random() * 1.8, vz: -vz * 0.25 + (Math.random() - 0.5) * 2,
        size: 0.12 + Math.random() * 0.12, life: 0.22 + Math.random() * 0.28, opacity: 1, gravity: -11, drag: 0.8,
      });
    }
  }

  trick(x, y, z) {
    for (let i = 0; i < 5; i++) {
      this.sparks.spawn(x + (Math.random() - 0.5) * 0.6, y + 0.15, z + (Math.random() - 0.5) * 0.6, {
        spread: 2.2, up: 1.4, size: 0.1 + Math.random() * 0.12, life: 0.3, opacity: 0.7, gravity: -4, drag: 1.2,
      });
    }
  }

  burst(x, y, z, color = 0xd7ff3f) {
    for (let i = 0; i < 22; i++) {
      this.letters.spawn(x, y, z, {
        spread: 6, up: 5, size: 0.14 + Math.random() * 0.2, life: 0.7 + Math.random() * 0.6,
        color, opacity: 1, gravity: -5, drag: 1.1,
      });
    }
    for (let i = 0; i < 12; i++) {
      this.sparks.spawn(x, y, z, {
        spread: 5, up: 4, size: 0.16, life: 0.5, opacity: 0.8, gravity: -3, drag: 0.8,
      });
    }
  }

  update(dt) {
    this.dust.update(dt);
    this.sparks.update(dt);
    this.letters.update(dt);
  }
}

