function physicsStep(dt, acts, first) {
  if (game.bailing > 0) { stepBail(dt); return; }

  if (first) {
    handleFlicks(acts.flicks);
  }
  handleJump({
    ...acts,
    jumpPressed: first && acts.jumpPressed,
    jumpReleased: first && acts.jumpReleased,
  }, dt);

  if (phys.grind) {
    stepGrind(dt, acts);
  } else if (!phys.grounded) {
    stepAir(dt, acts);
  } else {
    stepGround(dt, acts);
  }

  if (phys.grounded) {
    phys.airTime = 0;
    phys.spin = 0;
  }
}

