609: function buildRail(scene, metal, darkMetal, a, b, y, options = {}) {
610:   const group = new THREE.Group();
611:   const ax = a[0], az = a[1], bx = b[0], bz = b[1];
612:   const dx = bx - ax, dz = bz - az;
613:   const length = Math.hypot(dx, dz);
614:   const angle = Math.atan2(dx, dz);
615: 
616:   const dir3 = new THREE.Vector3(dx / length, 0, dz / length);
617:   const up3 = new THREE.Vector3(0, 1, 0);
618:   const top = new THREE.Mesh(new THREE.CylinderGeometry(options.radius || 0.055, options.radius || 0.055, length, 10), metal);
619:   top.quaternion.setFromUnitVectors(up3, dir3);
620:   top.position.set((ax + bx) / 2, y, (az + bz) / 2);
621:   top.castShadow = true;
622:   group.add(top);
623: 
624:   // support posts
625:   const count = Math.max(2, Math.round(length / 3.2));
626:   for (let i = 0; i <= count; i++) {
627:     const t = i / count;
628:     const px = ax + dx * t, pz = az + dz * t;
629:     const post = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.05, y, 8), darkMetal);
630:     post.position.set(px, y / 2, pz);
631:     post.castShadow = true;
632:     group.add(post);
633:     const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.13, 0.035, 10), darkMetal);
634:     foot.position.set(px, 0.02, pz);
635:     group.add(foot);
636:   }
637: 
638:   // orange paint bands
639:   if (!options.plain) {
640:     for (let i = 0; i < 3; i++) {
641:       const t = 0.18 + i * 0.32;
642:       const band = new THREE.Mesh(
643:         new THREE.CylinderGeometry(0.062, 0.062, 0.26, 10),
644:         new THREE.MeshStandardMaterial({ color: 0xff5a1f, roughness: 0.6 })
645:       );
646:       band.quaternion.setFromUnitVectors(up3, dir3);
647:       band.position.set(ax + dx * t, y, az + dz * t);
648:       group.add(band);
649:     }
650:   }
651: 
652:   scene.add(group);
653:   return { ax, az, bx, bz, y, length, group, width: options.width || 0.5 };
654: }
