function buildRail(scene, metal, darkMetal, a, b, y, options = {}) {
  const group = new THREE.Group();
  const ax = a[0], az = a[1], bx = b[0], bz = b[1];
  const dx = bx - ax, dz = bz - az;
  const length = Math.hypot(dx, dz);
  const angle = Math.atan2(dx, dz);

  const dir3 = new THREE.Vector3(dx / length, 0, dz / length);
  const up3 = new THREE.Vector3(0, 1, 0);
  const top = new THREE.Mesh(new THREE.CylinderGeometry(options.radius || 0.055, options.radius || 0.055, length, 10), metal);
  top.quaternion.setFromUnitVectors(up3, dir3);
  top.position.set((ax + bx) / 2, y, (az + bz) / 2);
  top.castShadow = true;
  group.add(top);

  // support posts
  const count = Math.max(2, Math.round(length / 3.2));
  for (let i = 0; i <= count; i++) {
    const t = i / count;
    const px = ax + dx * t, pz = az + dz * t;
    const post = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.05, y, 8), darkMetal);
    post.position.set(px, y / 2, pz);
    post.castShadow = true;
    group.add(post);
    const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.13, 0.035, 10), darkMetal);
    foot.position.set(px, 0.02, pz);
    group.add(foot);
  }

  // orange paint bands
  if (!options.plain) {
    for (let i = 0; i < 3; i++) {
      const t = 0.18 + i * 0.32;
      const band = new THREE.Mesh(
        new THREE.CylinderGeometry(0.062, 0.062, 0.26, 10),
        new THREE.MeshStandardMaterial({ color: 0xff5a1f, roughness: 0.6 })
      );
      band.quaternion.setFromUnitVectors(up3, dir3);
      band.position.set(ax + dx * t, y, az + dz * t);
      group.add(band);
    }
  }

  scene.add(group);
  return { ax, az, bx, bz, y, length, group, width: options.width || 0.5 };
}

