  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x6b5842, roughness: 1 });
  let px = 0, pz = 0;
  for (let i = 0; i < 8; i++) {
    const seg = new THREE.Mesh(new THREE.CylinderGeometry(0.18 - i * 0.008, 0.22 - i * 0.007, 1.25, 7), trunkMat);
    px += Math.sin(i * 0.35) * 0.16;
    pz += Math.cos(i * 0.2) * 0.05;
    seg.position.set(px, 0.6 + i * 1.18, pz);
    seg.rotation.z = Math.sin(i * 0.35) * 0.09;
    seg.castShadow = true;
    g.add(seg);
  }
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3f6b42, roughness: 0.9, side: THREE.DoubleSide });
  for (let i = 0; i < 9; i++) {
    const shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.quadraticCurveTo(0.6, 0.25, 2.8, 0);
    shape.quadraticCurveTo(0.6, -0.25, 0, 0);
    const geo = new THREE.ShapeGeometry(shape);
    const leaf = new THREE.Mesh(geo, leafMat);
    leaf.position.set(px, 9.6, pz);
    leaf.rotation.y = (i / 9) * Math.PI * 2;
    leaf.rotation.z = -0.32 - Math.random() * 0.25;
    leaf.rotation.x = 0.15;
    leaf.castShadow = true;
    g.add(leaf);
  }
  g.position.set(x, 0, z);
  g.scale.setScalar(scale);
  scene.add(g);
}

