const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGE: ' + e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/tmp/opencode/v-menu.png' });
  await page.getByRole('button', { name: 'Start', exact: true }).click();
  await page.waitForTimeout(2000);
  await page.screenshot({ path: '/tmp/opencode/v-start.png' });
  const st = await page.evaluate(() => {
    const s = window.__skate;
    let inst = 0, meshes = 0;
    s.scene.traverse(o => { if (o.isInstancedMesh) inst++; if (o.isMesh) meshes++; });
    return {
      mode: s.game.mode, pos: [s.phys.x, s.phys.y, s.phys.z].map(n => +n.toFixed(2)),
      grounded: s.phys.grounded,
      calls: s.renderer.info.render.calls, tris: s.renderer.info.render.triangles,
      inst, meshes, contactVisible: s.skater.contactShadow.visible,
      contactY: +s.skater.contactShadow.position.y.toFixed(3),
    };
  });
  console.log('STATE', JSON.stringify(st));
  await page.evaluate(() => __skate.teleport(0, 4, 0));
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/opencode/v-park.png' });
  await page.evaluate(() => __skate.teleport(-18, 2, 1.2));
  await page.waitForTimeout(700);
  await page.screenshot({ path: '/tmp/opencode/v-funbox.png' });
  // jump to see shadow fade
  await page.keyboard.down('w');
  await page.waitForTimeout(500);
  await page.keyboard.press('j');
  await page.waitForTimeout(300);
  const air = await page.evaluate(() => ({ y: +__skate.phys.y.toFixed(2), shadow: __skate.skater.contactShadow.visible, op: +__skate.skater.contactShadow.material.opacity.toFixed(2) }));
  console.log('AIR', JSON.stringify(air));
  await page.screenshot({ path: '/tmp/opencode/v-air.png' });
  await page.keyboard.up('w');
  await page.waitForTimeout(800);
  console.log('ERRORS', errors.length ? errors.join('\n') : 'none');
  await browser.close();
})();

